package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var TempRecData TempRec

func isInputDone() bool { return WsEofFlag == "Y" }

func formatZZ9_9(v decimal.Decimal) string {
	// PIC ZZ9.9  width 5, 3 integer digits, 1 fractional
	return formatEdited(v, 3, 1, []byte{'Z', 'Z', '9'}, false, false)
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	// PIC -ZZ9.99  sign + ZZ9.99
	// 3 integer digits, 2 fractional, Z,Z,9
	s := formatEdited(v, 3, 2, []byte{'Z', 'Z', '9'}, true, true)
	// formatEdited with sign already includes sign char
	return s
}

func formatEdited(v decimal.Decimal, intDigits int, fracDigits int, intMasks []byte, withSign bool, signIsMinus bool) string {
	neg := v.Sign() < 0
	abs := v.Abs()
	// Ensure scale = fracDigits (value already at correct scale; truncate/pad)
	// For safety, truncate toward zero to scale (MOVE semantics)
	// But values passed are already correctly scaled.
	abs = abs.Truncate(int32(fracDigits))

	// Extract integer and fractional parts
	// Use string representation with fixed scale
	// Multiply to get integer representation
	mult := decimal.New(1, int32(fracDigits)) // 10^fracDigits
	scaled := abs.Mul(mult)                   // integer value of abs*10^frac
	// scaled is integral
	s := scaled.StringFixed(0) // no exponent
	// s may be large; ensure at least fracDigits+1 chars
	// Split into int and frac
	var intPartStr, fracPartStr string
	if fracDigits > 0 {
		if len(s) <= fracDigits {
			// pad with leading zeros
			s = strings.Repeat("0", fracDigits+1-len(s)) + s
		}
		intPartStr = s[:len(s)-fracDigits]
		fracPartStr = s[len(s)-fracDigits:]
	} else {
		intPartStr = s
		fracPartStr = ""
	}

	// Handle high-order truncation: keep low-order intDigits digits
	if len(intPartStr) > intDigits {
		intPartStr = intPartStr[len(intPartStr)-intDigits:]
	} else if len(intPartStr) < intDigits {
		intPartStr = strings.Repeat("0", intDigits-len(intPartStr)) + intPartStr
	}

	// Apply Z suppression to integer part
	outInt := make([]byte, intDigits)
	for i := 0; i < intDigits; i++ {
		outInt[i] = intPartStr[i]
	}
	// Z suppression: left to right, Z positions with '0' become space until first non-suppressed
	// But a '9' always prints, even if zero
	for i := 0; i < intDigits; i++ {
		if intMasks[i] == 'Z' {
			if outInt[i] == '0' {
				// check if any non-zero/non-space to the right that is not suppressed? Actually COBOL suppresses until first non-zero digit.
				// Determine if all remaining integer digits (including current) that are not suppressed are zero?
				// Simplified: if all digits from i to end that are significant are zero, but we have a mandatory 9 at end.
				// Standard rule: scan left to right, if digit is '0' and no non-zero has been encountered yet, and not the last mandatory 9 beyond?
				// For ZZ9 pattern: leading zeros become spaces, but the final 9 always shows 0.
				// So we can implement: keep a flag seenNonZero
				// If not yet seen non-zero, and current digit is '0', then space if mask is Z
				// If digit is non-zero, mark seen
				// We need to know seenNonZero ahead? So we need to scan correctly.
				// Do a prior check for seen.
				break
			} else {
				break
			}
		}
	}
	seen := false
	for i := 0; i < intDigits; i++ {
		if outInt[i] != '0' {
			seen = true
		}
		if intMasks[i] == 'Z' && !seen {
			// Need to check if there is any non-zero later; if not, still suppress this zero unless it's the only?
			// For ZZ9, zeros before the final 9 should be suppressed if no non-zero seen.
			// So check if any later digit is non-zero
			hasLaterNonZero := false
			for j := i + 1; j < intDigits; j++ {
				if intPartStr[j] != '0' {
					hasLaterNonZero = true
					break
				}
			}
			if !hasLaterNonZero {
				// This Z zero is leading and should be space (the final 9 will show 0)
				outInt[i] = ' '
			} else {
				if outInt[i] == '0' {
					outInt[i] = ' '
				}
			}
			if outInt[i] != ' ' {
				seen = true
			}
		} else {
			// '9' position: always keep digit
			seen = true
		}
		// Actually need to handle case where a Z position had '0' but later non-zero exists -> space, still not seen
		// The above handles.
		// But if we replaced with space we should not set seen
		if outInt[i] == ' ' {
			// remain not seen unless later
			// keep seen as before (only if we already had non-zero)
			if !seen {
				// check if we had earlier non-zero; if not, seen stays false
			}
		}
	}
	// Re-evaluate seen correctly with simple loop:
	// Reset and do proper Z logic
	// Simpler: if int part numeric value ==0 -> all Z become space
	intValZero := true
	for _, c := range intPartStr {
		if c != '0' {
			intValZero = false
			break
		}
	}
	if intValZero {
		for i := 0; i < intDigits; i++ {
			if intMasks[i] == 'Z' {
				outInt[i] = ' '
			} else {
				outInt[i] = '0'
			}
		}
	} else {
		// general leading zero suppression
		for i := 0; i < intDigits; i++ {
			if intMasks[i] == 'Z' && outInt[i] == '0' {
				// check if any non-zero before this? Actually we need to see if all previous are spaces/zero
				// Determine if prefix up to i is all zeros
				prefixAllZero := true
				for k := 0; k <= i; k++ {
					if intPartStr[k] != '0' {
						prefixAllZero = false
						break
					}
				}
				// also check if there is a non-zero later? No, if prefix all zero we suppress
				if prefixAllZero {
					// need to ensure not all zeros (but we already handled all zero case)
					// Actually if value = 100, intPartStr="100", i=0 -> '1' not zero so not suppressed
					// value=010 -> i0 '0' prefixAllZero true -> space, i1 '1' not zero -> keep
					outInt[i] = ' '
				}
			}
		}
	}

	var b strings.Builder
	if withSign {
		if neg {
			b.WriteByte('-')
		} else {
			b.WriteByte(' ')
		}
	}
	for _, c := range outInt {
		b.WriteByte(c)
	}
	if fracDigits > 0 {
		b.WriteByte('.')
		// fracPartStr may need leading zeros
		if len(fracPartStr) < fracDigits {
			fracPartStr = strings.Repeat("0", fracDigits-len(fracPartStr)) + fracPartStr
		} else if len(fracPartStr) > fracDigits {
			fracPartStr = fracPartStr[:fracDigits]
		}
		b.WriteString(fracPartStr)
	}
	return b.String()
}

func formatPIC99(v int64) string {
	// PIC 99 zero padded width 2, low-order truncation
	v = v % 100
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

var tempFile *os.File
var tempReader *bufio.Reader
var tempScanner *bufio.Scanner

func MAIN_PARA() {
	OPEN_TEMP()
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	CLOSE_TEMP()
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func OPEN_TEMP() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		if os.IsNotExist(err) {
			tempFile = nil
			tempReader = nil
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	tempFile = f
	tempReader = bufio.NewReader(f)
}

func CLOSE_TEMP() {
	if tempFile != nil {
		tempFile.Close()
	}
}

func READ_PARA() {
	if tempReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := tempReader.ReadString('\n')
	if err != nil && len(line) == 0 {
		WsEofFlag = "Y"
		return
	}
	// Remove trailing \n \r
	line = strings.TrimRight(line, "\r\n")
	// Pad with spaces to record length 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	// Parse fields
	TempRecData.TcSensor = line[0:4]
	digits := line[4:8]
	// PIC 9(3)V9 : 4 digits implied decimal 1
	digits = strings.TrimSpace(digits)
	if digits == "" {
		digits = "0"
	}
	// digits should be numeric; if contains spaces, treat as 0?
	// Remove any non-digit? COBOL would have spaces only from padding, but our slice is exact.
	n := int64(0)
	for _, ch := range digits {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	TempRecData.TcF = decimal.New(n, -1)
	if err != nil && err.Error() == "EOF" {
		// still have a record, next read will be EOF
	}
	// Peek next? Actually AT END only on next read when no line.
	// Our handling: if err == io.EOF and we just read a line, we have a valid record; next call will hit EOF.
	// To detect EOF correctly, we already check len==0 above.
	if err != nil {
		// check if underlying is EOF and we consumed last line without newline: still valid, but mark for next?
		// We'll leave flag N for this record; next READ will return EOF.
		// Need to know if file ended: if err == io.EOF, next read will be empty.
		// We could set a flag to indicate next is EOF, but simpler: if err != nil and we read data, we still keep it.
		// On next call, ReadString will return 0, EOF.
	}
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := TempRecData.TcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	WsC = div.Round(2)
	if WsC.Sign() < 0 {
		WsFreeze++
		// PIC 99 low-order truncation (keep modulo 100)
		WsFreeze = WsFreeze % 100
	}
	WsCount++
	WsCount = WsCount % 100
	WsFEd = formatZZ9_9(TempRecData.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", TempRecData.TcSensor, WsFEd, WsCEd)
	READ_PARA()
}

func main() {
	MAIN_PARA()
}
